def readme(title, what, edges, lang, provider, slug, twin_path, catalog_path, env_block, run_cmd):
    edge_lines = "\n".join(f"- {e}" for e in edges)
    return f'''# {title} ({provider.title()})

{what}

## What this means

The call waits for the command to finish and returns exit code and output. A
non-zero exit code is not an SDK error.

## Edge cases

{edge_lines}

## Run

```sh
cd examples/{lang}/{provider}/process/{slug}
cp .env.example .env
# Fill in the values below, then:
{run_cmd}
```

{"Requires Go 1.26.0+ and this checkout." if lang=="go" else "Requires Node.js 20/22/24.15+ and npm 11.19.0."} Skip copying if `.env` already exists.
{"Local check: `GOWORK=off go test ./...`." if lang=="go" else ""}

### Environment

```dotenv
{env_block}
```

## Warnings

- Needs an existing sandbox.
- Closing the handle leaves the sandbox as it is. Closing the client closes
  your connection to the provider.

## Related

- [{ "typescript" if lang=="go" else "go" } twin]({twin_path})
- Catalog: [{catalog_path}]({catalog_path})
'''

created = []
for op, meta in ops.items():
  for provider in ("daytona", "modal"):
    slug = meta["slug_go"][provider]
    # Go
    gdir = ROOT / "go" / provider / "process" / slug
    gdir.mkdir(parents=True, exist_ok=True)
    go_body = meta.get(f"go_run_{provider}", meta.get("go_run"))
    (gdir / "main.go").write_text(daytona_go_main(go_body) if provider=="daytona" else modal_go_main(go_body))
    (gdir / "go.mod").write_text(go_mod(slug, provider))
    if provider == "daytona":
      env = "DAYTONA_API_KEY=\nDAYTONA_SANDBOX_ID=\n\n# Optional Daytona endpoint and target overrides.\n# DAYTONA_API_URL=https://app.daytona.io/api\n# DAYTONA_TARGET=\n" + meta.get("env_extra_daytona", "")
    else:
      env = "MODAL_TOKEN_ID=\nMODAL_TOKEN_SECRET=\nMODAL_APP_NAME=\nMODAL_ENVIRONMENT=main\nMODAL_SANDBOX_ID=\n" + meta.get("env_extra_modal", "")
    (gdir / ".env.example").write_text(env)
    twin = f"../../../../typescript/{provider}/process/{meta['slug_ts'][provider]}/README.md"
    (gdir / "README.md").write_text(readme(
      meta["title"], meta["what"], meta["edge"], "go", provider, slug, twin, "../../../README.md", env, "go run ."))
    created.append(str(gdir))

    # TS
    tslug = meta["slug_ts"][provider]
    tdir = ROOT / "typescript" / provider / "process" / tslug
    (tdir / "src").mkdir(parents=True, exist_ok=True)
    ts_body = meta.get(f"ts_run_{provider}", meta.get("ts_run"))
    (tdir / "src" / "main.ts").write_text(daytona_ts_main(ts_body) if provider=="daytona" else modal_ts_main(ts_body))
    (tdir / "package.json").write_text(json.dumps(ts_pkg(tslug, provider), indent=2) + "\n")
    (tdir / "tsconfig.json").write_text(json.dumps(tsconfig, indent=2) + "\n")
    (tdir / ".gitignore").write_text("dist/\nnode_modules/\n.env\n")
    (tdir / ".env.example").write_text(env)
    twin = f"../../../../go/{provider}/process/{slug}/README.md"
    (tdir / "README.md").write_text(readme(
      meta["title"], meta["what"], meta["edge"], "typescript", provider, tslug, twin, "../../../README.md", env, "npm install && npm run build && npm start"))
    created.append(str(tdir))

print(f"created {len(created)} projects")
for c in created:
  print(c)
