(async () => {
  const errors = [];
  window.addEventListener('error', (e) => errors.push('error:' + e.message + ' @ ' + e.filename + ':' + e.lineno));
  window.addEventListener('unhandledrejection', (e) => errors.push('rejection:' + String(e.reason)));
  window.__kitErrors = errors;
  location.reload();
