})()

(() => {
  const out = [];
  const origError = console.error.bind(console);
  const origWarn = console.warn.bind(console);
  console.error = (...args) => { out.push(['error', args.map(a => { try { return typeof a === 'string' ? a : (a && a.stack) || JSON.stringify(a) || String(a); } catch { return String(a); } }).join(' ')]); origError(...args); };
  console.warn = (...args) => { out.push(['warn', args.map(String).join(' ')]); origWarn(...args); };
  window.addEventListener('error', (e) => out.push(['window.error', e.message, e.filename, e.lineno, e.error && e.error.stack]));
  window.addEventListener('unhandledrejection', (e) => out.push(['rejection', String(e.reason && e.reason.stack || e.reason)]));
  window.__captured = out;
  return 'hooks installed';
})()

