export const DOC_PROVIDERS = [
  { id: "daytona", label: "Daytona" },
  { id: "modal", label: "Modal" },
] as const;

export type DocProviderId = (typeof DOC_PROVIDERS)[number]["id"];

export const DEFAULT_DOC_PROVIDER: DocProviderId = "daytona";

export const DOC_PROVIDER_STORAGE_KEY = "sandbox-kit.docs.provider";

export function isDocProviderId(value: string): value is DocProviderId {
  return DOC_PROVIDERS.some((provider) => provider.id === value);
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useLayoutEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import {
  DEFAULT_DOC_PROVIDER,
  DOC_PROVIDER_STORAGE_KEY,
  DOC_PROVIDERS,
  isDocProviderId,
  type DocProviderId,
} from "@/lib/providers";

type ProviderContextValue = {
  provider: DocProviderId;
  setProvider: (id: DocProviderId) => void;
  providers: typeof DOC_PROVIDERS;
};

const ProviderContext = createContext<ProviderContextValue | null>(null);

export function ProviderProvider({ children }: { children: ReactNode }) {
  const [provider, setProviderState] = useState<DocProviderId>(DEFAULT_DOC_PROVIDER);

  useLayoutEffect(() => {
    try {
      const stored = localStorage.getItem(DOC_PROVIDER_STORAGE_KEY);
      if (stored && isDocProviderId(stored)) {
        setProviderState(stored);
      }
    } catch {
      // ignore
    }
  }, []);

  const setProvider = useCallback((id: DocProviderId) => {
    setProviderState(id);
    try {
      localStorage.setItem(DOC_PROVIDER_STORAGE_KEY, id);
    } catch {
      // ignore
    }
  }, []);

  const value = useMemo(
    () => ({
      provider,
      setProvider,
      providers: DOC_PROVIDERS,
    }),
    [provider, setProvider],
  );

  return (
    <ProviderContext.Provider value={value}>{children}</ProviderContext.Provider>
  );
}

export function useDocProvider(): ProviderContextValue {
  const ctx = useContext(ProviderContext);
  if (!ctx) {
    throw new Error("useDocProvider must be used within ProviderProvider");
  }
  return ctx;
}

export function ProviderSelect({ className }: { className?: string }) {
  const { provider, setProvider, providers } = useDocProvider();

  return (
    <label
      className={
        className ??
        "ms-auto inline-flex items-center gap-2 text-sm text-fd-muted-foreground"
      }
    >
      <span className="sr-only">Provider</span>
      <select
        aria-label="Provider"
        className="rounded-md border border-fd-border bg-fd-background px-2 py-1 text-sm font-medium text-fd-foreground outline-none focus-visible:ring-2 focus-visible:ring-fd-ring"
        value={provider}
        onChange={(event) => {
          const next = event.target.value;
          if (isDocProviderId(next)) setProvider(next);
        }}
      >
        {providers.map((item) => (
          <option key={item.id} value={item.id}>
            {item.label}
          </option>
        ))}
      </select>
    </label>
  );
}

export function ForProvider({
  id,
  children,
}: {
  id: DocProviderId | DocProviderId[];
  children: ReactNode;
}) {
  const { provider } = useDocProvider();
  const ids = Array.isArray(id) ? id : [id];
  if (!ids.includes(provider)) return null;
  return children;
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useId,
  useMemo,
  type ComponentProps,
  type ReactNode,
} from "react";
import {
  Tabs as BaseTabs,
  TabsContent as BaseTabsContent,
  TabsList as BaseTabsList,
  TabsTrigger as BaseTabsTrigger,
} from "fumadocs-ui/components/tabs";
import { cn } from "@/lib/cn";
import { ProviderSelect } from "@/components/provider-context";

type TabsContextValue = {
  items?: string[];
  collection: string[];
};

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabContext() {
  const ctx = useContext(TabsContext);
  if (!ctx) throw new Error("You must wrap your component in <Tabs>");
  return ctx;
}

function escapeValue(v: string) {
  return v.toLowerCase().replace(/\s/, "-");
}

type BaseTabsProps = ComponentProps<typeof BaseTabs>;

export type TabsProps = Omit<BaseTabsProps, "value" | "onValueChange"> & {
  items?: string[];
  defaultIndex?: number;
  label?: ReactNode;
  /**
   * Show the provider dropdown on the language tab row.
   * Defaults to true when `groupId` is `"language"`.
   */
  showProvider?: boolean;
};

function TabsList({
  className,
  ...props
}: ComponentProps<typeof BaseTabsList>) {
  return (
    <BaseTabsList
      {...props}
      className={(s) =>
        cn(
          "flex w-full items-center gap-3.5 overflow-x-auto px-4 text-fd-secondary-foreground not-prose",
          typeof className === "function" ? className(s) : className,
        )
      }
    />
  );
}

function TabsTrigger({
  className,
  ...props
}: ComponentProps<typeof BaseTabsTrigger>) {
  return (
    <BaseTabsTrigger
      {...props}
      className={(s) =>
        cn(
          "inline-flex items-center gap-2 whitespace-nowrap border-b border-transparent py-2 text-sm font-medium text-fd-muted-foreground transition-colors [&_svg]:size-4 hover:text-fd-accent-foreground disabled:pointer-events-none disabled:opacity-50 data-[active]:border-fd-primary data-[active]:text-fd-primary",
          typeof className === "function" ? className(s) : className,
        )
      }
    />
  );
}

export function Tabs({
  ref,
  className,
  items,
  label,
  defaultIndex = 0,
  defaultValue = items ? escapeValue(items[defaultIndex]!) : undefined,
  showProvider,
  children,
  ...props
}: TabsProps) {
  const collection = useMemo(() => [] as string[], []);
  const withProvider =
    showProvider ?? (props.groupId === "language" && Boolean(items));

  return (
    <BaseTabs
      ref={ref}
      className={(s) =>
        cn(
          "my-4 flex flex-col overflow-hidden rounded-xl border bg-fd-secondary",
          typeof className === "function" ? className(s) : className,
        )
      }
      defaultValue={defaultValue}
      {...props}
    >
      {items && (
        <TabsList>
          {label && (
            <span className="my-auto me-auto text-sm font-medium">{label}</span>
          )}
          {items.map((item) => (
            <TabsTrigger key={item} value={escapeValue(item)}>
              {item}
            </TabsTrigger>
          ))}
