/** Public file URL. Honors the GitHub Pages base (`/kit/`) when the site is built for it. */
export function assetUrl(path: string) {
  const base = import.meta.env.BASE_URL ?? "/";
  return `${base}${path.replace(/^\//, "")}`;
}

/**
 * Root-relative site path with `BASE_URL` applied once.
 * Pass this to fumadocs page actions — they also call `withBasePath`, so do not
 * pre-prefix with `assetUrl`.
 */
export function sitePath(path: string) {
  const normalized = path.startsWith("/") ? path : `/${path}`;
  return normalized;
}

/** Absolute URL for static assets and markdown (GitHub Pages or current origin). */
export function absoluteSiteUrl(path: string) {
  const base = (import.meta.env.BASE_URL ?? "/").replace(/\/$/, "");
  const normalized = path.startsWith("/") ? path : `/${path}`;
  const withBase =
    !base || normalized === base || normalized.startsWith(`${base}/`)
      ? normalized
      : `${base}${normalized}`;
  if (typeof window !== "undefined") {
    return `${window.location.origin}${withBase}`;
  }
  return `https://sandbox-kit.github.io${withBase}`;
}

